INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 160, 101, 1, 1, 110, 1.5, 1, 0, 105, 122601, 0.029, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 120, 102, 0, 2, 105, 2.5, 2, 0, 111, 122401, 0.014, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 350, 103, 0, 3, 110, 2.5, 3, 1, 105, 122501, 0.017, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 130, 104, 0, 4, 110, 1.5, 4, 0, 105, 107501, 0.016, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 160, 105, 1, 5, 110, 2.5, 5, 0, 105, 107601, 0.014, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 255, 106, 0, 6, 120, 3.5, 6, 1, 103, 107801, 0.029, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 160, 107, 1, 7, 120, 3.5, 7, 0, 103, 110601, 0.013, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 350, 108, 0, 8, 110, 2.5, 8, 1, 103, 110401, 0.014, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 130, 109, 0, 9, 105, 1.5, 9, 0, 100, 110501, 0.012, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 200, 110, 1, 10, 105, 2.5, 10, 0, 103, 115701, 0.014, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 350, 111, 0, 11, 105, 2.5, 11, 1, 103, 113601, 0.071, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 130, 112, 0, 12, 120, 1.5, 12, 0, 103, 107901, 0.014, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 200, 113, 1, 13, 110, 1.5, 13, 0, 105, 108001, 0.022, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 160, 114, 1, 14, 110, 2.5, 14, 0, 108, 110301, 0.031, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 130, 115, 0, 15, 110, 0.5, 15, 0, 105, 107701, 0.036, 1, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 350, 116, 0, 16, 110, 3.5, 16, 1, 95, 113101, 0.048, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 130, 117, 0, 17, 105, 1.5, 17, 0, 105, 113301, 0.043, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 130, 118, 0, 18, 105, 1.5, 18, 0, 95, 113201, 0.018, 1, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 160, 119, 1, 19, 110, 2.5, 19, 0, 108, 117001, 0.021, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 255, 120, 0, 20, 110, 2.5, 20, 1, 105, 113501, 0.036, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 350, 121, 0, 21, 105, 2.5, 21, 1, 105, 113401, 0.02, 0, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 130, 122, 0, 22, 110, 2.5, 22, 0, 105, 110101, 0.018, 1, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 160, 123, 1, 23, 105, 3.5, 23, 0, 111, 110001, 0.03, 0, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 130, 124, 0, 24, 110, 1.5, 24, 0, 103, 117201, 0.027, 1, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 160, 125, 1, 25, 105, 3.5, 25, 0, 108, 117301, 0.02, 0, 2);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 350, 126, 0, 26, 110, 2.5, 26, 1, 105, 117401, 0.04, 0, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 350, 127, 0, 27, 110, 3.5, 27, 1, 105, 117101, 0.009, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 255, 128, 0, 28, 120, 3.5, 28, 1, 105, 122901, 0.022, 0, 1);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 130, 129, 0, 29, 110, 2.5, 29, 0, 105, 122801, 0.028, 1, 3);
INSERT INTO `v1_98ae641c01c26336f3f46d39047238bee0e2281109429e2b54b8e88737b849da` VALUES ("海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 130, 130, 1, 30, 105, 3.5, 30, 0, 108, 122701, 0.023, 0, 2);
